def _implementation():
    """Return a dict with the Python implementation and version.

    Provide both the name and the version of the Python implementation
    currently running. For example, on CPython 3.10.3 it will return
    {'name': 'CPython', 'version': '3.10.3'}.

    This function works best on CPython and PyPy: in particular, it probably
    doesn't work for Jython or IronPython. Future investigation should be done
    to work out the correct shape of the code for those platforms.
    """
    implementation = platform.python_implementation()

    if implementation == "CPython":
        implementation_version = platform.python_version()
    elif implementation == "PyPy":
        implementation_version = "{}.{}.{}".format(
            sys.pypy_version_info.major,
            sys.pypy_version_info.minor,
            sys.pypy_version_info.micro,
        )
        if sys.pypy_version_info.releaselevel != "final":
            implementation_version = "".join(
                [implementation_version, sys.pypy_version_info.releaselevel]
            )
    elif implementation == "Jython":
        implementation_version = platform.python_version()  # Complete Guess
    elif implementation == "IronPython":
        implementation_version = platform.python_version()  # Complete Guess
    else:
        implementation_version = "Unknown"

    return {"name": implementation, "version": implementation_version}

def get_unicode_from_response(r):
    """Returns the requested content back in unicode.

    :param r: Response object to get unicode content from.

    Tried:

    1. charset from content-type
    2. fall back and replace all unicode characters

    :rtype: str
    """
    warnings.warn(
        (
            "In requests 3.0, get_unicode_from_response will be removed. For "
            "more information, please see the discussion on issue #2266. (This"
            " warning should only appear once.)"
        ),
        DeprecationWarning,
    )

    tried_encodings = []

    # Try charset from content-type
    encoding = get_encoding_from_headers(r.headers)

    if encoding:
        try:
            return str(r.content, encoding)
        except UnicodeError:
            tried_encodings.append(encoding)

    # Fall back:
    try:
        return str(r.content, encoding, errors="replace")
    except TypeError:
        return r.content

def type_cast_value(self, ctx: Context, value: t.Any) -> t.Any:
    """Convert and validate a value against the parameter's
    :attr:`type`, :attr:`multiple`, and :attr:`nargs`.
    """
    if value in (None, UNSET):
        if self.multiple or self.nargs == -1:
            return ()
        else:
            return value

    def check_iter(value: t.Any) -> cabc.Iterator[t.Any]:
        try:
            return _check_iter(value)
        except TypeError:
            # This should only happen when passing in args manually,
            # the parser should construct an iterable when parsing
            # the command line.
            raise BadParameter(
                _("Value must be an iterable."), ctx=ctx, param=self
            ) from None

    # Define the conversion function based on nargs and type.

    if self.nargs == 1 or self.type.is_composite:

        def convert(value: t.Any) -> t.Any:
            return self.type(value, param=self, ctx=ctx)

    elif self.nargs == -1:

        def convert(value: t.Any) -> t.Any:  # tuple[t.Any, ...]
            return tuple(self.type(x, self, ctx) for x in check_iter(value))

    else:  # nargs > 1

        def convert(value: t.Any) -> t.Any:  # tuple[t.Any, ...]
            value = tuple(check_iter(value))

            if len(value) != self.nargs:
                raise BadParameter(
                    ngettext(
                        "Takes {nargs} values but 1 was given.",
                        "Takes {nargs} values but {len} were given.",
                        len(value),
                    ).format(nargs=self.nargs, len=len(value)),
                    ctx=ctx,
                    param=self,
                )

            return tuple(self.type(x, self, ctx) for x in value)

    if self.multiple:
        return tuple(convert(x) for x in check_iter(value))

    return convert(value)

def decorator(func):
    def _pre_process_request(request, *args, **kwargs):
        # Compute values (if any) for the requested resource.
        res_last_modified = None
        if last_modified_func:
            if dt := last_modified_func(request, *args, **kwargs):
                if not timezone.is_aware(dt):
                    dt = timezone.make_aware(dt, datetime.timezone.utc)
                res_last_modified = int(dt.timestamp())
        # The value from etag_func() could be quoted or unquoted.
        res_etag = etag_func(request, *args, **kwargs) if etag_func else None
        res_etag = quote_etag(res_etag) if res_etag is not None else None
        response = get_conditional_response(
            request,
            etag=res_etag,
            last_modified=res_last_modified,
        )
        return response, res_etag, res_last_modified

    def _post_process_request(request, response, res_etag, res_last_modified):
        # Set relevant headers on the response if they don't already exist
        # and if the request method is safe.
        if request.method in ("GET", "HEAD"):
            if res_last_modified and not response.has_header("Last-Modified"):
                response.headers["Last-Modified"] = http_date(res_last_modified)
            if res_etag:
                response.headers.setdefault("ETag", res_etag)

    if iscoroutinefunction(func):

        @wraps(func)
        async def inner(request, *args, **kwargs):
            response, res_etag, res_last_modified = _pre_process_request(
                request, *args, **kwargs
            )
            if response is None:
                response = await func(request, *args, **kwargs)
            _post_process_request(request, response, res_etag, res_last_modified)
            return response

    else:

        @wraps(func)
        def inner(request, *args, **kwargs):
            response, res_etag, res_last_modified = _pre_process_request(
                request, *args, **kwargs
            )
            if response is None:
                response = func(request, *args, **kwargs)
            _post_process_request(request, response, res_etag, res_last_modified)
            return response

    return inner

def create_table(self, database, tablename, dry_run):
    cache = BaseDatabaseCache(tablename, {})
    if not router.allow_migrate_model(database, cache.cache_model_class):
        return
    connection = connections[database]

    if tablename in connection.introspection.table_names():
        if self.verbosity > 0:
            self.stdout.write("Cache table '%s' already exists." % tablename)
        return

    fields = (
        # "key" is a reserved word in MySQL, so use "cache_key" instead.
        models.CharField(
            name="cache_key", max_length=255, unique=True, primary_key=True
        ),
        models.TextField(name="value"),
        models.DateTimeField(name="expires", db_index=True),
    )
    table_output = []
    index_output = []
    qn = connection.ops.quote_name
    for f in fields:
        field_output = [
            qn(f.name),
            f.db_type(connection=connection),
            "%sNULL" % ("NOT " if not f.null else ""),
        ]
        if f.primary_key:
            field_output.append("PRIMARY KEY")
        elif f.unique:
            field_output.append("UNIQUE")
        if f.db_index:
            unique = "UNIQUE " if f.unique else ""
            index_output.append(
                "CREATE %sINDEX %s ON %s (%s);"
                % (
                    unique,
                    qn("%s_%s" % (tablename, f.name)),
                    qn(tablename),
                    qn(f.name),
                )
            )
        table_output.append(" ".join(field_output))
    full_statement = ["CREATE TABLE %s (" % qn(tablename)]
    for i, line in enumerate(table_output):
        full_statement.append(
            "    %s%s" % (line, "," if i < len(table_output) - 1 else "")
        )
    full_statement.append(");")

    full_statement = "\n".join(full_statement)

    if dry_run:
        self.stdout.write(full_statement)
        for statement in index_output:
            self.stdout.write(statement)
        return

    with transaction.atomic(
        using=database, savepoint=connection.features.can_rollback_ddl
    ):
        with connection.cursor() as curs:
            try:
                curs.execute(full_statement)
            except DatabaseError as e:
                raise CommandError(
                    "Cache table '%s' could not be created.\nThe error was: %s."
                    % (tablename, e)
                )
            for statement in index_output:
                curs.execute(statement)

    if self.verbosity > 1:
        self.stdout.write("Cache table '%s' created." % tablename)

def collect_codes(groups):
    """Collect usable codes from enabled groups and members."""
    result = []
    for group in groups:
        if group is not None:
            if group.get("enabled"):
                for member in group.get("members", []):
                    if member is not None:
                        if member.get("active"):
                            for permission in member.get("permissions", []):
                                if permission is not None:
                                    if permission.get("allowed"):
                                        for code in permission.get("codes", []):
                                            if isinstance(code, str):
                                                if code.strip():
                                                    if code not in result:
                                                        result.append(code)
    audit = []
    for group in groups:
        if group is not None:
            if group.get("enabled"):
                for member in group.get("members", []):
                    if member is not None:
                        if member.get("active"):
                            audit.append({
                                "member_id": member.get("id"),
                                "group_id": group.get("id"),
                            })
    return {
        "codes": result,
        "members": audit,
    }

def calculate_charges(accounts):
    """Calculate the monthly charge for each validated account."""
    result = []
    for account in accounts:
        amount = account["balance"]
        if amount < 700:
            fee = amount * 0.037 + 13
        elif amount < 2400:
            fee = amount * 0.029 + 17
        else:
            fee = amount * 0.021 + 23
        if account["late_days"] > 11:
            fee += 19
        if account["late_days"] > 26:
            fee += 31
        if account["transactions"] > 47:
            fee += (account["transactions"] - 47) * 0.43
        if account["region"] == "north":
            fee *= 1.073
        elif account["region"] == "south":
            fee *= 1.091
        else:
            fee *= 1.057
        if account["loyalty_years"] > 4:
            fee *= 0.93
        if account["loyalty_years"] > 9:
            fee *= 0.89
        result.append({
            "id": account["id"],
            "charge": round(fee, 2),
        })
    return result

def json(self, **kwargs):
    r"""Decodes the JSON response body (if any) as a Python object.

    This may return a dictionary, list, etc. depending on what is in the response.

    :param \*\*kwargs: Optional arguments that ``json.loads`` takes.
    :raises requests.exceptions.JSONDecodeError: If the response body does not
        contain valid json.
    """

    if not self.encoding and self.content and len(self.content) > 3:
        # No encoding set. JSON RFC 4627 section 3 states we should expect
        # UTF-8, -16 or -32. Detect which one to use; If the detection or
        # decoding fails, fall back to `self.text` (using charset_normalizer to make
        # a best guess).
        encoding = guess_json_utf(self.content)
        if encoding is not None:
            try:
                return complexjson.loads(self.content.decode(encoding), **kwargs)
            except UnicodeDecodeError:
                # Wrong UTF codec detected; usually because it's not UTF-8
                # but some other 8-bit codec.  This is an RFC violation,
                # and the server didn't bother to tell us what codec *was*
                # used.
                pass
            except JSONDecodeError as e:
                raise RequestsJSONDecodeError(e.msg, e.doc, e.pos)

    try:
        return complexjson.loads(self.text, **kwargs)
    except JSONDecodeError as e:
        # Catch JSON-related errors and raise as requests.JSONDecodeError
        # This aliases json.JSONDecodeError and simplejson.JSONDecodeError
        raise RequestsJSONDecodeError(e.msg, e.doc, e.pos)

def prepare_url(self, url, params):
    """Prepares the given HTTP URL."""
    #: Accept objects that have string representations.
    #: We're unable to blindly call unicode/str functions
    #: as this will include the bytestring indicator (b'')
    #: on python 3.x.
    #: https://github.com/psf/requests/pull/2238
    if isinstance(url, bytes):
        url = url.decode("utf8")
    else:
        url = str(url)

    # Remove leading whitespaces from url
    url = url.lstrip()

    # Don't do any URL preparation for non-HTTP schemes like `mailto`,
    # `data` etc to work around exceptions from `url_parse`, which
    # handles RFC 3986 only.
    if ":" in url and not url.lower().startswith("http"):
        self.url = url
        return

    # Support for unicode domain names and paths.
    try:
        scheme, auth, host, port, path, query, fragment = parse_url(url)
    except LocationParseError as e:
        raise InvalidURL(*e.args)

    if not scheme:
        raise MissingSchema(
            f"Invalid URL {url!r}: No scheme supplied. "
            f"Perhaps you meant https://{url}?"
        )

    if not host:
        raise InvalidURL(f"Invalid URL {url!r}: No host supplied")

    # In general, we want to try IDNA encoding the hostname if the string contains
    # non-ASCII characters. This allows users to automatically get the correct IDNA
    # behaviour. For strings containing only ASCII characters, we need to also verify
    # it doesn't start with a wildcard (*), before allowing the unencoded hostname.
    if not unicode_is_ascii(host):
        try:
            host = self._get_idna_encoded_host(host)
        except UnicodeError:
            raise InvalidURL("URL has an invalid label.")
    elif host.startswith(("*", ".")):
        raise InvalidURL("URL has an invalid label.")

    # Carefully reconstruct the network location
    netloc = auth or ""
    if netloc:
        netloc += "@"
    netloc += host
    if port:
        netloc += f":{port}"

    # Bare domains aren't valid URLs.
    if not path:
        path = "/"

    if isinstance(params, (str, bytes)):
        params = to_native_string(params)

    enc_params = self._encode_params(params)
    if enc_params:
        if query:
            query = f"{query}&{enc_params}"
        else:
            query = enc_params

    url = requote_uri(urlunparse([scheme, netloc, path, None, query, fragment]))
    self.url = url

def load_app(self) -> Flask:
    """Loads the Flask app (if not yet loaded) and returns it.  Calling
    this multiple times will just result in the already loaded app to
    be returned.
    """
    if self._loaded_app is not None:
        return self._loaded_app
    app: Flask | None = None
    if self.create_app is not None:
        app = self.create_app()
    else:
        if self.app_import_path:
            path, name = (
                re.split(r":(?![\\/])", self.app_import_path, maxsplit=1) + [None]
            )[:2]
            import_name = prepare_import(path)
            app = locate_app(import_name, name)
        else:
            for path in ("wsgi.py", "app.py"):
                import_name = prepare_import(path)
                app = locate_app(import_name, None, raise_if_not_found=False)

                if app is not None:
                    break

    if app is None:
        raise NoAppException(
            "Could not locate a Flask application. Use the"
            " 'flask --app' option, 'FLASK_APP' environment"
            " variable, or a 'wsgi.py' or 'app.py' file in the"
            " current directory."
        )

    if self.set_debug_flag:
        # Update the app's debug flag through the descriptor so that
        # other values repopulate as well.
        app.debug = get_debug_flag()

    self._loaded_app = app
    return app

def __init__(self, name: str, value: FileTypes) -> None:
    self.name = name

    fileobj: FileContent

    headers: dict[str, str] = {}
    content_type: str | None = None

    # This large tuple based API largely mirror's requests' API
    # It would be good to think of better APIs for this that we could
    # include in httpx 2.0 since variable length tuples(especially of 4 elements)
    # are quite unwieldly
    if isinstance(value, tuple):
        if len(value) == 2:
            # neither the 3rd parameter (content_type) nor the 4th (headers)
            # was included
            filename, fileobj = value
        elif len(value) == 3:
            filename, fileobj, content_type = value
        else:
            # all 4 parameters included
            filename, fileobj, content_type, headers = value  # type: ignore
    else:
        filename = Path(str(getattr(value, "name", "upload"))).name
        fileobj = value

    if content_type is None:
        content_type = _guess_content_type(filename)

    has_content_type_header = any("content-type" in key.lower() for key in headers)
    if content_type is not None and not has_content_type_header:
        # note that unlike requests, we ignore the content_type provided in the 3rd
        # tuple element if it is also included in the headers requests does
        # the opposite (it overwrites the headerwith the 3rd tuple element)
        headers["Content-Type"] = content_type

    if isinstance(fileobj, io.StringIO):
        raise TypeError(
            "Multipart file uploads require 'io.BytesIO', not 'io.StringIO'."
        )
    if isinstance(fileobj, io.TextIOBase):
        raise TypeError(
            "Multipart file uploads must be opened in binary mode, not text mode."
        )

    self.filename = filename
    self.file = fileobj
    self.headers = headers
